+  },
+  // Absent parallelism flags mean 1 (SGLang's own default), so callers can do
+  // arithmetic without null checks.
+  sizeOf(cell, name) {
+    const f = config.flagOf(cell, name);
+    return f ? Number(f.split(/[\s=]/)[1]) || 1 : 1;
